func lengthOfLongestSubstring(_ s: String) -> Int {
    var last: [Character: Int] = [:]
    var left = 0, best = 0
    for (i, c) in s.enumerated() {
        if let j = last[c], j >= left { left = j + 1 }
        last[c] = i
        best = max(best, i - left + 1)
    }
    return best
}
